import os

base_path = "/home/USER/runs/paper/qwen-h0-u1-turns/frozen/held-out-reference-3/play/users/u065/system/state"

def search_for_json_files(path, target_strings, max_depth=2):
    results = []
    if max_depth < 0:
        return results

    try:
        entries = os.listdir(path)
    except:
        return results

    for entry in entries:
        full_path = os.path.join(path, entry)
        if os.path.isfile(full_path) and entry.endswith('.json'):
            try:
                with open(full_path) as f:
                    content = f.read()
                    # Check if any target string is in the content
                    for ts in target_strings:
                        if ts in content:
                            results.append(full_path)
            except:
                pass
        elif os.path.isdir(full_path):
            results.extend(search_for_json_files(full_path, target_strings, max_depth-1))

    return results

# Search for task files
